const fs = require('fs');
const path = require('path');

const sourcePath = path.join(__dirname, 'README.md');
const targetPath = path.join(__dirname, 'INDEX.md');

const source = fs.readFileSync(sourcePath, 'utf8');
const headings = source
  .split(/\r?\n/)
  .map((line) => line.trim())
  .filter((line) => line.startsWith('#'));

fs.writeFileSync(targetPath, headings.join('\n') + '\n', 'utf8');

console.log(`Wrote ${headings.length} heading(s) to INDEX.md`);

